<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>MakeMyDemo.com — Teaser</title>
<style>
@font-face{font-family:'Inter';src:url('assets/Inter.ttf')}
*{margin:0;padding:0;box-sizing:border-box}
html,body{background:#09090B;overflow:hidden}
body{font-family:'Inter',sans-serif;color:#FAFAFA}
#root{position:relative;width:1920px;height:1080px;background:#09090B;overflow:hidden}
.scene{position:absolute;inset:0;display:flex;align-items:center;justify-content:center}
.s1wrap{display:flex;flex-direction:column;align-items:center;gap:72px}
#s1h{font-size:128px;font-weight:700;letter-spacing:-0.03em;color:#FAFAFA}
#urlbar{display:flex;align-items:center;gap:18px;border:2px solid rgba(250,250,250,0.28);border-radius:18px;padding:34px 48px;width:1000px;background:rgba(250,250,250,0.04)}
#urltext{font-size:40px;font-weight:500;color:#FAFAFA;white-space:nowrap}
#caret{width:4px;height:48px;background:#DFE104;border-radius:2px;flex:none}
.s2wrap{display:flex;flex-direction:column;align-items:center;gap:84px}
#s2h{font-size:96px;font-weight:700;letter-spacing:-0.03em;color:#FAFAFA}
.s2row{display:flex;align-items:center;gap:96px}
#frame{width:540px;height:310px;border:2px solid rgba(250,250,250,0.28);border-radius:24px;background:rgba(250,250,250,0.03);display:flex;align-items:center;justify-content:center;flex:none}
.tracks{display:flex;flex-direction:column;gap:48px;width:640px}
.track{display:flex;flex-direction:column;gap:16px}
.tlabel{font-size:26px;font-weight:600;letter-spacing:0.22em;text-transform:uppercase;color:rgba(250,250,250,0.75)}
.tline{display:block;height:4px;background:rgba(250,250,250,0.14);border-radius:2px;overflow:hidden}
.tfill{display:block;height:100%;background:#DFE104}
.s3wrap{display:flex;flex-direction:column;align-items:center;gap:56px}
#s3h{font-size:64px;font-weight:500;letter-spacing:0.01em;color:rgba(250,250,250,0.85)}
#logo{font-size:150px;font-weight:800;letter-spacing:-0.04em;line-height:1;color:#FAFAFA}
#dot{color:#DFE104;display:inline-block}
#logobar{width:180px;height:10px;background:#DFE104;border-radius:5px}
</style>
</head>
<body>
<div id="root" data-composition-id="main" data-start="0" data-width="1920" data-height="1080" data-fps="24" data-duration="8">

<section class="scene" id="scene1" data-start="0" data-duration="2.8" data-track-index="0">
<div class="s1wrap">
<h1 id="s1h">Paste a link.</h1>
<div id="urlbar">
<span id="urltext">https://yourproduct.com</span>
<span id="caret"></span>
</div>
</div>
</section>

<section class="scene" id="scene2" data-start="2.8" data-duration="2.8" data-track-index="0">
<div class="s2wrap">
<h1 id="s2h">Get a first cut.</h1>
<div class="s2row">
<div id="frame">
<svg width="84" height="96" viewBox="0 0 84 96"><polygon points="0,0 84,48 0,96" fill="#DFE104"/></svg>
</div>
<div class="tracks">
<div class="track" id="t1"><span class="tlabel">AI script</span><span class="tline"><span class="tfill"></span></span></div>
<div class="track" id="t2"><span class="tlabel">Product visuals</span><span class="tline"><span class="tfill"></span></span></div>
<div class="track" id="t3"><span class="tlabel">Music</span><span class="tline"><span class="tfill"></span></span></div>
</div>
</div>
</div>
</section>

<section class="scene" id="scene3" data-start="5.6" data-duration="2.4" data-track-index="0">
<div class="s3wrap">
<h2 id="s3h">Review &amp; export MP4.</h2>
<div id="logo">MakeMyDemo<span id="dot">.</span></div>
<div id="logobar"></div>
</div>
</section>

</div>
<script src="assets/gsap.min.js"></script>
<script>
window.__timelines = {};
document.fonts.ready.then(function () {
  gsap.set('#s1h', { autoAlpha: 0, y: 40 });
  gsap.set('#urlbar', { autoAlpha: 0 });
  gsap.set('#urltext', { clipPath: 'inset(0 100% 0 0)' });
  gsap.set(['#scene2', '#scene3'], { autoAlpha: 0 });
  gsap.set('#s2h', { autoAlpha: 0, y: 40 });
  gsap.set('#frame', { autoAlpha: 0 });
  gsap.set('.track', { autoAlpha: 0, y: 24 });
  gsap.set('.tfill', { scaleX: 0, transformOrigin: 'left center' });
  gsap.set('#s3h', { autoAlpha: 0, y: 40 });
  gsap.set('#logo', { autoAlpha: 0, y: 40 });
  gsap.set('#dot', { autoAlpha: 0, scale: 0 });
  gsap.set('#logobar', { scaleX: 0, transformOrigin: 'center' });

  var tl = gsap.timeline({ paused: true });

  tl.to('#s1h', { autoAlpha: 1, y: 0, duration: 0.6, ease: 'power3.out' }, 0)
    .to('#urlbar', { autoAlpha: 1, duration: 0.4, ease: 'power2.out' }, 0.45)
    .to('#urltext', { clipPath: 'inset(0 0% 0 0)', duration: 1.1, ease: 'steps(20)' }, 0.7)
    .fromTo('#caret', { autoAlpha: 1 }, { autoAlpha: 0, duration: 0.22, repeat: 5, yoyo: true, ease: 'none' }, 0.9)
    .to('#scene1', { autoAlpha: 0, duration: 0.35, ease: 'power2.in' }, 2.45)

    .set('#scene2', { autoAlpha: 1 }, 2.8)
    .to('#s2h', { autoAlpha: 1, y: 0, duration: 0.5, ease: 'power3.out' }, 2.85)
    .to('#frame', { autoAlpha: 1, duration: 0.5, ease: 'power2.out' }, 3.15)
    .to('.track', { autoAlpha: 1, y: 0, duration: 0.45, ease: 'power3.out', stagger: 0.15 }, 3.35)
    .to('#t1 .tfill', { scaleX: 1, duration: 0.9, ease: 'power2.inOut' }, 3.6)
    .to('#t2 .tfill', { scaleX: 1, duration: 0.9, ease: 'power2.inOut' }, 3.8)
    .to('#t3 .tfill', { scaleX: 1, duration: 0.9, ease: 'power2.inOut' }, 4.0)
    .to('#scene2', { autoAlpha: 0, duration: 0.35, ease: 'power2.in' }, 5.25)

    .set('#scene3', { autoAlpha: 1 }, 5.6)
    .to('#s3h', { autoAlpha: 1, y: 0, duration: 0.5, ease: 'power3.out' }, 5.7)
    .to('#logo', { autoAlpha: 1, y: 0, duration: 0.6, ease: 'power3.out' }, 6.1)
    .to('#dot', { autoAlpha: 1, scale: 1, duration: 0.35, ease: 'back.out(2)' }, 6.5)
    .to('#logobar', { scaleX: 1, duration: 0.4, ease: 'power2.inOut' }, 6.6);

  window.__timelines['main'] = tl;
  window.__renderReady = true;
});
</script>
</body>
</html>
